// Phase 3 / Module 14: DSA Fundamentals (analysis, searching, sorting).
"use strict";
const { chain, graph, table, svgWrap, esc } = require("./render");
const { mcq, task } = require("./lib");

const lessons = [];
const tx = (x, y, s, size = 13, anchor = "middle") => `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" fill="currentColor" font-family="system-ui,sans-serif">${esc(s)}</text>`;
// A row of array cells; marks: {index: "fill colour"}; labels under the cells.
const arrayRow = (values, x0, y, marks = {}, cell = 44) =>
  values.map((v, i) => `<rect x="${x0 + i * cell}" y="${y}" width="${cell - 4}" height="${cell - 4}" rx="4" fill="${marks[i] || "rgba(127,127,127,.10)"}" stroke="currentColor" stroke-width="1.5"/>` + tx(x0 + i * cell + (cell - 4) / 2, y + (cell - 4) / 2 + 5, v, 15)).join("");
const BLUE = "rgba(56,139,253,.35)", GREEN = "rgba(46,160,67,.35)", AMBER = "rgba(210,153,34,.35)";

// ---------------------------------------------------------------- 1
lessons.push({
  title: "Introduction to DSA: Problem Solving and Algorithm Analysis",
  minutes: 50,
  learn: ["Define data structure, algorithm and abstract data type", "Follow a repeatable method for solving coding problems", "Use Big O, Omega and Theta and best, average and worst cases", "Trace an algorithm by hand with a dry run"],
  why: "Placement tests and interviews test whether you can pick the right structure and algorithm and explain its cost. A method removes the panic of a blank page.",
  realWorld: "Google Maps finds routes with graph algorithms; a phone contact list searches with binary search or hashing; an e-commerce site ranks results with sorting.",
  simple: "A <strong>data structure</strong> organises data (list, dictionary, tree). An <strong>algorithm</strong> is a step-by-step procedure that solves a problem. Together they decide how fast and how memory-hungry a solution is.",
  detail: `<h3>Abstract data types</h3>
<p>An <strong>ADT</strong> describes <em>what</em> operations a structure offers, not how it works inside: a Stack has <code>push</code> and <code>pop</code>; a Queue has <code>enqueue</code> and <code>dequeue</code>; a Map has <code>get</code> and <code>put</code>. Python implements them with lists, deques and dictionaries.</p>
<h3>A problem-solving method (UMPIRE)</h3>
${table(["Step", "Do this"], [["Understand", "restate the problem; inputs, outputs, constraints, edge cases"], ["Match", "which pattern fits: search, sort, two pointers, hashing, recursion, graph?"], ["Plan", "describe the steps in words or pseudocode; choose the structure"], ["Implement", "write clean code"], ["Review", "dry-run on the sample and on edge cases (empty, one item, duplicates, negatives)"], ["Evaluate", "state time and space complexity; think about improvements"]])}
<h3>Asymptotic notation</h3>
${table(["Symbol", "Meaning", "Plain words"], [["O(f)", "upper bound", "no worse than f for large n"], ["&Omega;(f)", "lower bound", "at least f for large n"], ["&Theta;(f)", "tight bound", "exactly f up to constants"]])}
<p>Example: linear search is &Omega;(1) in the best case (found first), O(n) in the worst case (last or absent) and &Theta;(n) on average. Cases describe <em>which input</em>; notations describe <em>how we bound the growth</em>. Interviews usually quote the worst-case O.</p>
<h3>Using constraints</h3>
<p>The input size hints at the intended complexity (about 10<sup>8</sup> simple operations per second in Python is optimistic; 10<sup>6</sup> to 10<sup>7</sup> is safer): n &le; 20 allows O(2<sup>n</sup>); n &le; 500 allows O(n&sup3;); n &le; 5,000 allows O(n&sup2;); n &le; 10<sup>6</sup> needs O(n log n) or O(n).</p>`,
  syntax: { code: `# pseudocode for linear search\nfor i in range(len(items)):\n    if items[i] == target:\n        return i\nreturn -1`, note: "Write the steps before the code." },
  diagram: chain("A problem-solving loop", "Left to right: understand, match a pattern, plan, implement, review with a dry run, evaluate complexity.",
    [{ k: "proc", t: "Understand" }, { k: "proc", t: "Match\npattern" }, { k: "proc", t: "Plan" }, { k: "proc", t: "Implement" }, { k: "proc", t: "Review\n(dry run)" }, { k: "term", t: "Evaluate\nO( )" }], { w: 100, gap: 18, hgt: 52 }),
  example: { code: `def linear_search(items, target):\n    comparisons = 0\n    for index, value in enumerate(items):\n        comparisons += 1\n        if value == target:\n            return index, comparisons\n    return -1, comparisons\n\ndata = [4, 8, 15, 16, 23, 42]\nprint(linear_search(data, 4))\nprint(linear_search(data, 23))\nprint(linear_search(data, 99))\nprint(linear_search([], 1))`, out: `(0, 1)\n(4, 5)\n(-1, 6)\n(-1, 0)` },
  lineByLine: [["comparisons += 1", "Counts the work done: the quantity Big O describes."], ["return index, comparisons", "Best case: the target is first, so one comparison."], ["linear_search(data, 99)", "Worst case: every one of the 6 items is examined."], ["linear_search([], 1)", "An edge case: an empty list does zero comparisons and returns -1."]],
  dryRun: { intro: "Searching 23 in <code>[4, 8, 15, 16, 23, 42]</code>:", headers: ["Step", "Value", "Equal to 23?", "Comparisons"], rows: [["index 0", "4", "no", "1"], ["index 1", "8", "no", "2"], ["index 2", "15", "no", "3"], ["index 3", "16", "no", "4"], ["index 4", "23", "yes: return 4", "5"]] },
  realExample: { intro: "Using the constraints: with n up to 100,000 an O(n²) pair check is too slow, so a set (O(n)) is the intended solution.", code: `def has_pair(nums, target):\n    seen = set()\n    for x in nums:\n        if target - x in seen:\n            return True\n        seen.add(x)\n    return False\nprint(has_pair([3, 9, 14, 2], 16), has_pair([3, 9], 100))`, out: `True False` },
  mistakes: ["Starting to code before understanding the constraints.", "Testing only the sample input.", "Confusing best case with Omega and worst case with O (they are different ideas).", "Ignoring space complexity.", "Not saying the complexity aloud in an interview."],
  practices: ["Write the examples and edge cases first.", "Dry-run by hand before running.", "Always finish with time and space complexity."],
  interview: ["What is the difference between a data structure and an algorithm?", "What are O, Omega and Theta?", "What is the best/average/worst case of linear search?", "How do input constraints guide your solution?"],
  practiceQs: ["What complexity does n = 10^5 suggest?", "List four edge cases for a function that finds the maximum of a list.", "Is O(n) always faster than O(n²) for n = 5? Why might it not matter?", "Define ADT with an example."],
  revision: ["Data structure + algorithm = solution.", "UMPIRE: understand, match, plan, implement, review, evaluate.", "O upper, Omega lower, Theta tight; best/average/worst.", "Constraints suggest complexity."],
  hinglish: "Data structure data ko sajaane ka tarika hai aur algorithm uska hal nikalne ke steps. Problem hal karne ke liye pehle samjho, pattern pehchano, plan likho, code likho, dry run karo aur complexity batao. Big O upper bound hai, Omega lower bound aur Theta tight bound.",
  quiz: [
    mcq("What is the worst case of linear search on n items?", ["O(1)", "O(log n)", "O(n)", "O(n²)"], 2, "The target is last or absent."),
    mcq("What does an ADT describe?", ["How data is stored in memory", "The operations a structure supports", "A programming language", "A sorting method"], 1, "What it does, not how."),
    mcq("What does Theta describe?", ["Upper bound only", "Lower bound only", "A tight bound", "Memory use"], 2, "Both an upper and a lower bound."),
    mcq("For n up to 20, which complexity is usually acceptable?", ["O(2^n)", "O(n!) for n = 100", "Only O(1)", "None"], 0, "2^20 is about a million."),
    mcq("What should you do right after writing a solution?", ["Submit immediately", "Dry-run it on sample and edge cases", "Delete the tests", "Add threads"], 1, "Review before you rely on it.")
  ],
  tasks: [task("Linear search with a counter", "Read a line of integers and then a target. Print the index of the first occurrence (or -1) and the number of comparisons made, separated by a space.", "nums = list(map(int, input().split()))\ntarget = int(input())\n# print: index comparisons\n", `nums = list(map(int, input().split()))\ntarget = int(input())\ncomparisons = 0\nindex = -1\nfor i, v in enumerate(nums):\n    comparisons += 1\n    if v == target:\n        index = i\n        break\nprint(index, comparisons)`, [["4 8 15 16\n15", "2 3"], ["4 8 15 16\n99", "-1 4"]], [["4 8 15 16\n15", "2 3"], ["4 8 15 16\n99", "-1 4"], ["7\n7", "0 1"], ["1 2 2 2\n2", "1 2"], ["5 4 3 2 1\n1", "4 5"]])],
});

