  realExample: { intro: "Merge overlapping time intervals: a classic sort-then-scan problem.", code: `def merge_intervals(intervals):\n    merged = []\n    for start, end in sorted(intervals):\n        if merged and start <= merged[-1][1]:\n            merged[-1][1] = max(merged[-1][1], end)\n        else:\n            merged.append([start, end])\n    return merged\nprint(merge_intervals([(8, 10), (1, 3), (2, 6), (15, 18), (17, 20)]))`, out: `[[1, 6], [8, 10], [15, 20]]` },
